(4870195, 707425, 3087, '<td valign="top">Nicely executed with strong composition, simple and uncluttered contents, even lighting and good colour saturation.</td>', 'Nicely executed with strong composition, simple and uncluttered contents, even lighting and good colour saturation.', '2008-08-06 12:56:00.000000', NULL, 1),
(4870200, 706813, 3087, '<td valign="top">A nice scene, I like the sense of strong light coming in and lighting up the world.</td>', 'A nice scene, I like the sense of strong light coming in and lighting up the world.', '2008-08-06 12:56:36.000000', NULL, 1),
(4870204, 707237, 3087, '<td valign="top">I like the extreme angle, looking down from a residential window. The motion blur in the one binman with wheely bin against the sharp details of the rest works well.</td>', 'I like the extreme angle, looking down from a residential window. The motion blur in the one binman with wheely bin against the sharp details of the rest works well.', '2008-08-06 12:57:21.000000', NULL, 1),
(4870205, 707253, 73942, '<td valign="top">Great original idea!</td>', 'Great original idea!', '2008-08-06 12:57:29.000000', NULL, 1),
(4870209, 707242, 3087, '<td valign="top">Almost abstract in it''s simplicity.</td>', 'Almost abstract in it''s simplicity.', '2008-08-06 12:57:48.000000', NULL, 1),
(4870210, 706787, 3087, '<td valign="top">I like this silhouette shot very much, both for the rich detail in the angler and also for the foreground reed shapes and the looser framing created by the reflections of trees on the other bank. The composition works so well.</td>', 'I like this silhouette shot very much, both for the rich detail in the angler and also for the foreground reed shapes and the looser framing created by the reflections of trees on the other bank. The composition works so well.', '2008-08-06 12:58:48.000000', NULL, 1),
(4870214, 707310, 3087, '<td valign="top">I love Lucky Charms. As a Brit, I encountered them on regular visits to family in Florida and my sister and I loved them so much that, as they weren''t then available in the UK, we''d bring a few boxes back in our luggage and insist our aunts and uncles bought some in theirs whenever they visited! <br/>I like the way the fridge provides lighting and environment and the way that your subject is so focused on the task!</td>', 'I love Lucky Charms. As a Brit, I encountered them on regular visits to family in Florida and my sister and I loved them so much that, as they weren''t then available in the UK, we''d bring a few boxes back in our luggage and insist our aunts and uncles bought some in theirs whenever they visited! I like the way the fridge provides lighting and environment and the way that your subject is so focused on the task!', '2008-08-06 13:00:29.000000', NULL, 1),
(4870218, 706865, 73942, '<td valign="top">strong composition</td>', 'strong composition', '2008-08-06 13:01:02.000000', NULL, 1),
