INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4872713, 707426, 91496, '<td valign="top">I love it.  I keep expecting an alien to pop out and attack me.  Lighting might be a little on the harse side.</td>', 'I love it.  I keep expecting an alien to pop out and attack me.  Lighting might be a little on the harse side.', '2008-08-07 13:43:42.000000', NULL, 1),
(4872788, 706516, 92285, '<td valign="top">flat no morning color</td>', 'flat no morning color', '2008-08-07 14:36:41.000000', NULL, 1),
