(4872800, 707306, 92285, '<td valign="top">wheres the inspiration here??</td>', 'wheres the inspiration here??', '2008-08-07 14:44:29.000000', NULL, 1),
(4872806, 707477, 92285, '<td valign="top">could be crisper, but good</td>', 'could be crisper, but good', '2008-08-07 14:46:37.000000', NULL, 1),
(4872987, 706519, 97082, '<td valign="top">Cool!!!!!!!</td>', 'Cool!!!!!!!', '2008-08-07 16:19:35.000000', NULL, 1),
(4873025, 707321, 77192, '<td valign="top">There''s something I''m not quite sure about with this pic, and I can''t quite put my finger on it. I like that you''ve silhouetted the pylon. I like that the overhead power lines lead me towards the sunset itself, I like the range of colours, and yet I feel there''s something not quite right somehow. Sorry to be no help lol.</td>', 'There''s something I''m not quite sure about with this pic, and I can''t quite put my finger on it. I like that you''ve silhouetted the pylon. I like that the overhead power lines lead me towards the sunset itself, I like the range of colours, and yet I feel there''s something not quite right somehow. Sorry to be no help lol.', '2008-08-07 16:46:49.000000', NULL, 1),
(4873028, 706627, 77192, '<td valign="top">The yellow is a bit bright, it distracts me from the dew itself</td>', 'The yellow is a bit bright, it distracts me from the dew itself', '2008-08-07 16:47:33.000000', NULL, 1),
(4873038, 707384, 77192, '<td valign="top">I''m thinking an Enzo shot here :-)<br/> <br/>(If you''re not <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=34938" rel="nofollow" target="_blank">hotpasta</a>, please take the fact that I''ve mistaken your shot for his as a sincere compliment, as I regard his work very highly)<br/> <br/>I do like blue tints on water shots, and I particularly like the shallow-DOF-like effect caused by the fog. You''ve captured it very well in this shot. The only think I''m not keen on are the reflections of the masts in the water, they look a tad pixellated, but I suspect it''s the way the water reflects the light and the 640-pixel resolution that causes this, a larger print would do it justice.<br/> <br/>Overall, an excellent shot. Well done.</td>', 'I''m thinking an Enzo shot here :-) (If you''re not  hotpasta, please take the fact that I''ve mistaken your shot for his as a sincere compliment, as I regard his work very highly) I do like blue tints on water shots, and I particularly like the shallow-DOF-like effect caused by the fog. You''ve captured it very well in this shot. The only think I''m not keen on are the reflections of the masts in the water, they look a tad pixellated, but I suspect it''s the way the water reflects the light and the 640-pixel resolution that causes this, a larger print would do it justice. Overall, an excellent shot. Well done.', '2008-08-07 16:53:55.000000', NULL, 1),
(4873045, 706917, 77192, '<td valign="top">Haha love it. I like the ironic coffe pic in the background. Looks like they need some of it.</td>', 'Haha love it. I like the ironic coffe pic in the background. Looks like they need some of it.', '2008-08-07 16:56:01.000000', NULL, 1),
(4873049, 706823, 77192, '<td valign="top">nice abstract</td>', 'nice abstract', '2008-08-07 16:57:03.000000', NULL, 1),
