(4883625, 707339, 31664, '<td valign="top">Nice shot of the cow,  its a shame the background looks a little blown out</td>', 'Nice shot of the cow,  its a shame the background looks a little blown out', '2008-08-12 19:51:38.000000', NULL, 1),
(4883628, 707353, 31664, '<td valign="top">Not sure about expressing the theme :) but a nice well composed shot.</td>', 'Not sure about expressing the theme :) but a nice well composed shot.', '2008-08-12 19:53:11.000000', NULL, 1),
(4883633, 706484, 59740, '<td valign="top">Great capture, beautiful light.</td>', 'Great capture, beautiful light.', '2008-08-12 19:54:57.000000', NULL, 1),
(4883643, 706059, 31664, '<td valign="top">Nice parking! Great Idea.  Would have liked a better exposed background,  the red tinge aloung the hill ridge and grass stems(?) that are OOF in the forground are just a little distracting from the main subject.</td>', 'Nice parking! Great Idea.  Would have liked a better exposed background,  the red tinge aloung the hill ridge and grass stems(?) that are OOF in the forground are just a little distracting from the main subject.', '2008-08-12 19:58:48.000000', NULL, 1),
