(4883653, 707421, 59740, '<td valign="top">This great shot would IMO be even better with the distracting green thing cropped off. The left part of the snake is out of focus anyway and doesn''t add much. Nice job.</td>', 'This great shot would IMO be even better with the distracting green thing cropped off. The left part of the snake is out of focus anyway and doesn''t add much. Nice job.', '2008-08-12 20:05:10.000000', NULL, 1),
(4883656, 704934, 59740, '<td valign="top">I don''t know how you tell if this is morning or evening but I like it anyway. Nice shot.</td>', 'I don''t know how you tell if this is morning or evening but I like it anyway. Nice shot.', '2008-08-12 20:06:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4883659, 707091, 59740, '<td valign="top">Nice photo. I don''t kow if basic editing would allow straightening of the pier but it looks a little strange listing to the right.</td>', 'Nice photo. I don''t kow if basic editing would allow straightening of the pier but it looks a little strange listing to the right.', '2008-08-12 20:08:01.000000', NULL, 1),
(4883662, 707238, 59740, '<td valign="top">I generally like photos through glass with their interesting reflections and distortions but this is a little too busy and cryptic for my taste. I might have narrowed my field to the section right of the doorway.</td>', 'I generally like photos through glass with their interesting reflections and distortions but this is a little too busy and cryptic for my taste. I might have narrowed my field to the section right of the doorway.', '2008-08-12 20:11:31.000000', NULL, 1),
(4883664, 707237, 59740, '<td valign="top">Clever take on the subject. It certainly says morning.</td>', 'Clever take on the subject. It certainly says morning.', '2008-08-12 20:12:27.000000', NULL, 1),
(4883668, 705620, 59740, '<td valign="top">Good photo. I think it would be even better without the bud on the right.</td>', 'Good photo. I think it would be even better without the bud on the right.', '2008-08-12 20:14:32.000000', NULL, 1),
